public BigDecimal calculate(DiscountPolicy policy, BigDecimal amount) {
    switch (policy) {
        case NO_DISCOUNT:
            return amount;
        case TEN_PERCENT_OFF:
            return amount.multiply(BigDecimal.valueOf(0.9));
        case FIXED_MINUS_FIFTY:
            return amount.subtract(BigDecimal.valueOf(50));
        default:
            throw new IllegalArgumentException("Unknown policy");
    }
}

